    if value is None or value == "" or value == "00000000":
        return None

    text = str(value)
    if len(text) != 8 or not text.isdigit():
        raise ValueError(f"invalid YYYYMMDD date: {text!r}")

    return date(int(text[:4]), int(text[4:6]), int(text[6:8]))


